// Mirrors backend/app/schemas (contracts.py, claims.py).
// TODO(Kissa): replace with types generated by `npx openapi-typescript`.

export type Role = 'citizen' | 'helper' | 'officer' | 'admin' | 'auditor'
export type Route = 'AUTO_APPROVE' | 'ASK_PROOF' | 'UNSURE'
export type DocumentKind = 'death_certificate' | 'claimant_cnic' | 'frc' | 'nikah_nama'

export type SessionUser = { id: string; name: string; role: Role; tenant_id: string; person_id: string | null }
export type LoginResult = { access_token: string; refresh_token: string; user: SessionUser }

export type Me = {
  id: string
  role: Role
  name: string | null
  person: { id: string; cnic: string; name: string } | null
}

// cnic is null when the family has not shared it with this helper (no active consent).
export type Family = { id: string; cnic: string | null; name: string; consent_active?: boolean }

export type DecisionSummary = {
  id: string
  route: Route
  reason_codes: string[]
  confidence: number
  rule_version: number
  model_id: string | null
  created_at: string
}

export type CaseView = {
  id: string
  reference: string
  status: string
  priority: number
  confidence: number | null
  claimant_person_id: string
  assigned_officer_id: string | null
  deceased_cnic: string | null
  created_at: string
  latest_decision: DecisionSummary | null
}

// A list row whose claimant no longer shares her details with this viewer (Security review H1):
// only the reference and status come back, never personal details or an id to open.
export type CaseStub = { reference: string; status: string; consent_active: false }
export type CaseRow = CaseView | CaseStub

export function isCaseStub(row: CaseRow): row is CaseStub {
  return (row as CaseStub).consent_active === false
}

// The same for an officer's payout-change list row without payout_account consent.
export type PayoutChangeStub = { id: string; case_id: string; case_reference: string; status: PayoutChangeStatus; hold_until: string; consent_active: false }

export function isPayoutChangeStub(row: PayoutChange | PayoutChangeStub): row is PayoutChangeStub {
  return (row as PayoutChangeStub).consent_active === false
}

export type Explanation = { reason_code: string; text_ur: string; text_en: string; audio_key: string; icon: string }

export type CitizenExplanation = {
  case_reference: string
  status: string
  route: Route | null
  explanations: Explanation[]
  missing_items: string[]
  entitlement_end: string | null
}

export type ClaimIn = {
  claimant_cnic: string
  claimant_name: string
  claimant_dob: string | null
  relation_claimed: 'widow' | 'son' | 'daughter'
  deceased_cnic: string | null
  deceased_name: string
  payout_iban: string
  documents: DocumentKind[]
}

export type AuditRow = {
  seq: number
  ts: string
  actor_type: string
  role: string | null
  action: string
  resource: string | null
  details: Record<string, unknown>
}

export type ConsentField = 'cnic' | 'family_record' | 'death_certificate' | 'payout_account' | 'case_details'

export type Consent = {
  id: string
  grantee_type: 'helper' | 'department'
  grantee_id: string
  grantee_name: string
  fields: ConsentField[]
  status: 'active' | 'withdrawn'
  created_at: string
  withdrawn_at: string | null
  // Open claims that need this department's access: it cannot be taken back until they are withdrawn/closed.
  needed_for_claims?: OpenClaim[]
}

export type OpenClaim = { id: string; reference: string; status: string; can_withdraw: boolean }

export type ConsentList = { fields: ConsentField[]; consents: Consent[] }

export type AccessLogRow = {
  seq: number
  ts: string
  action: string
  who: string
  role: string | null
  field: string | null
  basis: string | null
}

export type CorrectionField = 'name' | 'date_of_birth' | 'payout_account' | 'family_record'

export type RuleDef = { id: string; title?: string; basis?: string; reason?: string }

export type RuleVersionRow = {
  id: string
  ruleset: string
  version: number
  label: string
  status: 'live' | 'draft' | 'retired'
  effective_from: string | null
  thresholds: Record<string, number>
  rules: RuleDef[]
}

export type TwinOutcome = { route: string; reasons: string[]; entitlement_end: string | null }

export type TwinCase = { case: string; status: string; before: TwinOutcome; after: TwinOutcome; changed: string[]; applies_on_publish?: boolean }

// will_redecide / applies_on_publish: pending cases entitled on or after the draft's effective date (older backends omit them).
export type Simulation = { draft_version: number; checked: number; changed: number; will_redecide?: number; cases: TwinCase[] }

// Scam Shield (backend/app/api/scam.py)
export type ScamVerdict = 'LIKELY_SCAM' | 'LOOKS_GENUINE' | 'NOT_SURE'

export type ReportRoute = {
  id: string
  kind: 'call' | 'link' | 'sms' | 'info'
  name: string
  name_ur: string
  url: string | null
  confidence: string
  source: string | null
}

export type ScamChannel = 'sms' | 'whatsapp' | 'call' | 'link' | 'other'

// A link found in the message, checked in code and never opened (backend/app/scam/links.py).
export type ScamLink = {
  host: string
  registrable: string
  official: boolean
  official_label: string | null
  imitates: string | null
  findings: string[]
  fetched: boolean
}

export type ScamSensor = { name: string; status: string; model?: string | null; latency_ms?: number | null; cost_usd?: number | null }

export type ScamResult = {
  verdict: ScamVerdict
  confidence: number
  reasons: string[]
  reasons_ur: string[]
  case_cross_check: string | null
  case_cross_check_ur?: string | null
  model_id: string | null
  channel?: ScamChannel
  links?: ScamLink[]
  report_routes: ReportRoute[]
  // Screenshot / voice note: what the server read or heard (not stored).
  extracted?: { text: string; sender_found?: boolean; ocr_engine?: string; confidence?: number | null; language?: string }
  // Staff only.
  officer_note?: string
  sensors?: ScamSensor[]
}

export type ScamMapData = {
  total_checked: number
  by_verdict: Record<string, number>
  scams_by_type: Record<string, number>
  scams_by_area: Record<string, number>
  scams_by_hour: Record<string, number>
}

// SafeSwitch (backend/app/api/payout.py) + mock Raast title fetch (backend/app/mock/raast.py)
export type PayeeCheck = {
  status: 'OK' | 'ACCOUNT_NOT_FOUND' | 'UNAVAILABLE' | 'TIMEOUT'
  match_level: 'MATCH' | 'CLOSE_MATCH' | 'NO_MATCH' | 'UNAVAILABLE'
  masked_title: string | null
  account_type: 'ACCOUNT' | 'WALLET' | null
  account_holding: 'SINGLE' | 'JOINT' | null
  bank_code: string | null
  cnic_match: boolean | null
  reason_codes: string[]
  latency_ms: number
  simulated: boolean
  route: 'OK' | 'ASK_PROOF' | 'UNSURE'
}

export type PayoutChangeStatus = 'held' | 'flagged' | 'confirmed' | 'approved' | 'applied' | 'rejected' | 'cancelled'

export type PayoutChange = {
  id: string
  case_id: string
  status: PayoutChangeStatus
  payee_result: 'match' | 'close_match' | 'no_match' | 'unavailable'
  flags: string[]
  hold_until: string
  new_iban_last4: string
  requested_role: string
  confirmed: boolean
  applied_at: string | null
  created_at: string | null
  payee_check: PayeeCheck | null
  case_reference?: string
}
